class ListNode {
    int val;
    ListNode next;
    ListNode(int val) { this.val = val; }
}

public ListNode reverseList(ListNode head) {
    ListNode prev = null;
    ListNode current = head;

    while (current != null) {
        ListNode next = current.next;  // Save next node
        current.next = prev;           // Reverse the link
        prev = current;                // Move prev forward
        current = next;                // Move current forward
    }

    return prev;  // New head of reversed list
}

// Example usage:
// Original: 1 -> 2 -> 3 -> null
// After:    3 -> 2 -> 1 -> null

public ListNode reverseListRecursive(ListNode head) {
    // Base case: empty list or single node
    if (head == null || head.next == null) {
        return head;
    }

    // Recursively reverse the rest of the list
    ListNode newHead = reverseListRecursive(head.next);

    // Make the next node point back to current node
    head.next.next = head;

    // Remove the old forward link
    head.next = null;

    return newHead;  // Return the new head
}

// Example:
// reverseListRecursive(1 -> 2 -> 3 -> null)
// Step 1: Recurse to end, returns 3
// Step 2: 3.next = 2 (was 2 -> 3, now 3 -> 2)
// Step 3: 2.next = 1 (was 1 -> 2, now 2 -> 1)
// Result: 3 -> 2 -> 1 -> null

public class LinkedListReversal {

    static class ListNode {
        int val;
        ListNode next;
        ListNode(int val) { this.val = val; }
    }

    // Iterative solution
    public static ListNode reverse(ListNode head) {
        ListNode prev = null;
        ListNode current = head;

        while (current != null) {
            ListNode next = current.next;
            current.next = prev;
            prev = current;
            current = next;
        }

        return prev;
    }

    // Helper to print list
    public static void printList(ListNode head) {
        ListNode current = head;
        while (current != null) {
            System.out.print(current.val);
            if (current.next != null) System.out.print(" -> ");
            current = current.next;
        }
        System.out.println(" -> null");
    }

    public static void main(String[] args) {
        // Test case 1: Normal list
        ListNode head = new ListNode(1);
        head.next = new ListNode(2);
        head.next.next = new ListNode(3);
        head.next.next.next = new ListNode(4);

        System.out.print("Original: ");
        printList(head);

        ListNode reversed = reverse(head);
        System.out.print("Reversed: ");
        printList(reversed);

        // Test case 2: Empty list
        ListNode empty = null;
        System.out.println("Empty list reversed: " + reverse(empty));

        // Test case 3: Single node
        ListNode single = new ListNode(1);
        System.out.print("Single node: ");
        printList(reverse(single));
    }
}
